head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setScrollTop]<br/>GridView 컴포넌트의 세로 스크롤 위치를 설정합니다.",
    "validation" : [
        "top(필수) 파라미터로 세로 스크롤 위치를 픽셀(px)로 설정해야 합니다. (예: 0 = 최상단, 100 = 100px)",
        "drawType='virtual' 인 경우에 동작합니다.",
        "top(필수) 파라미터가 최대 높이 초과 시 최대값이 적용되어야 합니다.",
        "top(필수) 파라미터가 음수값이면 0 으로 처리되어야 합니다.",
        "setScrollTop() 로 스크롤 이동 시 onscrolly, onscrollstart, onscrollend 이벤트가 발생해야 합니다.",
    ]
}



scwin.gVar = { "evt" : { "onscrollstart" : false, "onscrollend" : false, "onscrolly" : false } };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 이벤트 발생 플래그 초기화
    scwin.gVar.evt = { "onscrollstart" : false, "onscrollend" : false, "onscrolly" : false };

    // 테스트 참고 라벨 — grp_comp 맨 위에 표시되도록 grid 생성 전 먼저 생성
    $c.gcm.createLabel('label="[전제] gridView drawType=virtual (30행, 높이 250px 로 세로 스크롤 발생)\n[절차] top 값(0 / 100 / 99999(최대초과) / -50(음수)) 선택 후 (setScrollTop 실행) 클릭\n[확인] 적용 scrollTop(getScrollTop) + onscrollstart/onscrollend/onscrolly 발생 여부"', '', 'label1');

    // dataList 생성 (30 행 — 뷰포트보다 데이터가 많아 세로 스크롤 확보)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 30);

    // 조건 설정 : drawType=virtual (setScrollTop 은 virtual 인 경우에만 동작)
    let properties = {
        drawType: "virtual",
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // 높이를 작게(250px) 설정 → 뷰포트에 일부 Row 만 표시되어 세로 스크롤 발생
    // onscrollstart / onscrollend / onscrolly 이벤트 바인딩 (@spec1 검증용)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:250px;" ev:onscrollstart="scwin.target1_onscrollstart" ev:onscrollend="scwin.target1_onscrollend" ev:onscrolly="scwin.target1_onscrolly">';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// onscrollstart 핸들러 — setScrollTop 으로 스크롤 이동 시작 시 발생
scwin.target1_onscrollstart = function (e) {
    scwin.gVar.evt.onscrollstart = true;
}



// onscrollend 핸들러 — setScrollTop 으로 스크롤 이동 종료 시 발생
scwin.target1_onscrollend = function (e) {
    scwin.gVar.evt.onscrollend = true;
}



// onscrolly 핸들러 — setScrollTop 으로 세로 스크롤 이동 시 발생
scwin.target1_onscrolly = function (e) {
    scwin.gVar.evt.onscrolly = true;
}



// setScrollTop 실행 — top(px) 위치로 세로 스크롤 이동
// @param top : 세로 스크롤 위치(px). 0 이상 정수. 최대 초과 시 최대값 적용. 음수는 0 처리.
// @return 없음. 이동은 렌더 의존값이므로 native setTimeout(500) 으로 갱신 후 getScrollTop() / 이벤트 발생 여부 확인
//  - 0     : 최상단 (getScrollTop() == 0)
//  - 100   : 100px 위치 (getScrollTop() == 100)
//  - 99999 : 최대 높이 초과 → 최대값 보정 (getScrollTop() == 최대 스크롤 위치, 99999 미만)
//  - -50   : 음수 → 0 처리 (getScrollTop() == 0)
scwin.btn_setScrollTop_onclick = function (e) {
    let top = Number(par_top.getValue());

    // 이벤트 발생 플래그 초기화
    scwin.gVar.evt = { "onscrollstart" : false, "onscrollend" : false, "onscrolly" : false };

    // setScrollTop 실행
    target1.setScrollTop(top);

    // 이동은 렌더 의존값 → native setTimeout(500) 으로 갱신 후 읽음
    setTimeout(function () {
        let applied = target1.getScrollTop();

        wf_body_bottom.getObj("scwin").setReturnValue("[top=" + top + " 적용 scrollTop] getScrollTop() : " + applied);
        wf_body_bottom.getObj("scwin").setReturnValue("[이벤트 발생] onscrollstart=" + scwin.gVar.evt.onscrollstart + ", onscrollend=" + scwin.gVar.evt.onscrollend + ", onscrolly=" + scwin.gVar.evt.onscrolly);
    }, 500);
}
